import React,{useCallback,useEffect,useMemo,useRef,useState}from'react';
import{ArrowLeft,BookOpen,Box,ChevronLeft,ChevronRight,Clock,ExternalLink,Filter,GitBranch,Globe2,Image as ImageIcon,Link2,Loader2,Map,Maximize2,Minus,Plus,RefreshCw,Save,Search,Settings,ShieldAlert,Trash2,Upload,X,ZoomIn,ZoomOut}from'lucide-react';
import TiptapEditor from'../TiptapEditor'; import{api}from'../../utils/api';
type Resource={id:string;novel_id:string;resource_type:string;parent_id?:string|null;name:string;subtype?:string;description?:string;visibility:'draft'|'published'|'private'|'unlisted';publication_status:'draft'|'published';display_order:number;data:any;updated_at:string;version?:number};
type Tab='overview'|'graph'|'maps'|'lore'|'artifacts'|'power'|'timelines'|'relationships'|'settings';
const tabs:[Tab,string,any][]=[['overview','نمای کلی',Globe2],['graph','گراف جهان',GitBranch],['maps','نقشه‌ها',Map],['lore','دانشنامه',BookOpen],['artifacts','آرتیفکت‌ها',Box],['power','سیستم‌های قدرت',ShieldAlert],['timelines','خطوط زمانی',Clock],['relationships','روابط',Link2],['settings','تنظیمات',Settings]];
const endpoint=(novelId:string)=>`/api/worldbuilding/${encodeURIComponent(novelId)}/resources`;
const stripHtml=(value:string)=>String(value||"").replace(/<[^>]*>/g," ").replace(/\s+/g," ").trim();
async function request(url:string,init:RequestInit={}){const token=api.getToken();const response=await fetch(url,{credentials:'same-origin',...init,headers:{...(init.body?{'Content-Type':'application/json'}:{}),...(token?{'X-CSRF-Token':token}:{}),...(init.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok){const error:any=new Error(body.error||`درخواست ناموفق بود (${response.status})`);error.fields=body.fields||{};error.status=response.status;throw error}return body;}
function useDialogFocus(){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const root=ref.current;if(!root)return;const previous=document.activeElement as HTMLElement|null,focusable=()=>[...root.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])')];focusable()[0]?.focus();const trap=(event:KeyboardEvent)=>{if(event.key!=='Tab')return;const items=focusable();if(!items.length)return;const first=items[0],last=items.at(-1)!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};root.addEventListener('keydown',trap);return()=>{root.removeEventListener('keydown',trap);previous?.focus()}},[]);return ref;}
function uploadImage(file:File,onProgress:(value:number)=>void){return new Promise<any>((resolve,reject)=>{const data=new FormData();data.append('file',file);const xhr=new XMLHttpRequest();xhr.open('POST','/api/upload/upload');xhr.withCredentials=true;const token=api.getToken();if(token)xhr.setRequestHeader('X-CSRF-Token',token);xhr.upload.onprogress=e=>{if(e.lengthComputable)onProgress(Math.round(e.loaded/e.total*100))};xhr.onerror=()=>reject(new Error('اتصال در حین بارگذاری قطع شد'));xhr.onload=()=>{let body:any={};try{body=JSON.parse(xhr.responseText)}catch{}if(xhr.status>=200&&xhr.status<300)resolve(body);else reject(new Error(body.error||`بارگذاری ناموفق بود (${xhr.status})`))};xhr.send(data)})}
function Visibility({value,onChange,disabled=false}:{value:any,onChange:(v:any)=>void,disabled?:boolean}){return <div className="grid sm:grid-cols-2 gap-3"><label className="text-xs font-bold">انتشار<select disabled={disabled} value={value.publicationStatus||'draft'} onChange={e=>onChange({...value,publicationStatus:e.target.value})} className="wb-input"><option value="draft">پیش‌نویس</option><option value="published">منتشرشده</option></select></label><label className="text-xs font-bold">سطح نمایش<select disabled={disabled} value={value.visibility||'draft'} onChange={e=>onChange({...value,visibility:e.target.value})} className="wb-input"><option value="published">منتشرشده — خوانندگان مجاز رمان</option><option value="private">خصوصی — فقط مالک/مدیر</option><option value="unlisted">فهرست‌نشده — فقط با لینک مستقیم</option><option value="draft">پیش‌نویس — فقط همکاران</option></select></label></div>}
export function EntityPicker({resources,value,onChange,disabled=false,label='موجودیت‌های مرتبط'}:{resources:Resource[];value:string[];onChange:(v:string[])=>void;disabled?:boolean;label?:string}){const[q,setQ]=useState(''),[type,setType]=useState(''),[limit,setLimit]=useState(50);const filtered=resources.filter(r=>!value.includes(r.id)&&(!q||r.name.toLowerCase().includes(q.toLowerCase()))&&(!type||r.resource_type===type));const options=filtered.slice(0,limit);return <fieldset disabled={disabled} className="rounded-xl border border-slate-700 p-3"><legend className="px-1 text-xs font-bold">{label}</legend><div className="flex flex-wrap gap-1 mb-2">{value.map(id=>{const r=resources.find(x=>x.id===id);return <button type="button" key={id} onClick={()=>onChange(value.filter(x=>x!==id))} className="rounded-full bg-violet-500/15 px-2 py-1 text-[10px]">{r?.name||'نامشخص'} <X className="inline w-3 h-3"/></button>})}</div><div className="grid grid-cols-2 gap-2"><input aria-label="جستجوی موجودیت‌های مرتبط" className="wb-input" value={q} onChange={e=>setQ(e.target.value)} placeholder="جستجو"/><select aria-label="فیلتر نوع موجودیت" className="wb-input" value={type} onChange={e=>setType(e.target.value)}><option value="">همه انواع</option>{[...new Set(resources.map(r=>r.resource_type))].map(x=><option key={x}>{x}</option>)}</select></div><div className="max-h-32 overflow-auto mt-2">{options.map(r=><button type="button" key={r.id} onClick={()=>onChange([...new Set([...value,r.id])])} className="block w-full text-left px-2 py-1 rounded hover:bg-slate-700 text-xs">+ {r.name} <span className="opacity-50">({r.resource_type})</span></button>)}{filtered.length>limit&&<button type="button" onClick={()=>setLimit(v=>v+50)} className="mt-2 text-xs text-violet-400">بارگذاری 50 مورد دیگر</button>}</div></fieldset>}
const loreFields=['summary','history','origins','government','leadership','capital','population','geography','beliefs','customs','traditions','laws','economy','military','allies','enemies','languages','importantPeople','importantLocations','notes'];
