const fmtDate=(v:string)=>new Date(v).toLocaleString('fa-IR-u-nu-latn');
function RevisionHistory({resource}:{resource?:Resource}){const[rows,setRows]=useState<any[]|null>(null),[error,setError]=useState('');if(!resource)return null;return <details onToggle={e=>{if(e.currentTarget.open&&rows===null)request(`${endpoint(resource.novel_id)}/${resource.id}/revisions`).then(x=>setRows(x.revisions||[])).catch(x=>setError(x.message))}} className="rounded-xl border border-slate-700 p-3"><summary className="cursor-pointer text-xs font-bold">تاریخچه نسخه‌ها</summary>{error&&<p className="text-rose-400 text-xs">{error}</p>}{rows?.length===0&&<p className="text-xs opacity-60">نسخه قبلی وجود ندارد.</p>}{rows?.map(x=><details key={x.id} className="mt-2 text-xs"><summary>Revision {x.revision} · {fmtDate(x.created_at)}</summary><pre className="max-h-52 overflow-auto whitespace-pre-wrap rounded bg-black/30 p-2">{JSON.stringify(x.snapshot,null,2)}</pre></details>)}</details>}
function MapSettings({map,maps,readOnly,onSave}:{map:Resource;maps:Resource[];readOnly:boolean;onSave:(v:any)=>Promise<void>}){const[d,setD]=useState<any>({name:map.name,subtype:map.subtype||'World',description:map.description||'',parentId:map.parent_id||'',displayOrder:map.display_order,visibility:map.visibility,publicationStatus:map.publication_status,data:map.data});useEffect(()=>setD({name:map.name,subtype:map.subtype||'World',description:map.description||'',parentId:map.parent_id||'',displayOrder:map.display_order,visibility:map.visibility,publicationStatus:map.publication_status,data:map.data}),[map.id,map.updated_at]);return <details className="mb-3 rounded-xl border border-slate-700 p-3"><summary className="cursor-pointer font-bold">تنظیمات نقشه</summary><div className="grid sm:grid-cols-2 gap-2 mt-2"><input disabled={readOnly} className="wb-input" value={d.name} onChange={e=>setD({...d,name:e.target.value})} placeholder="نام نقشه"/><select disabled={readOnly} className="wb-input" value={d.subtype} onChange={e=>setD({...d,subtype:e.target.value})}>{['World','Continent','Country','Region','City','Building','Dungeon','Custom'].map(x=><option key={x}>{x}</option>)}</select><textarea disabled={readOnly} className="wb-input" value={d.description} onChange={e=>setD({...d,description:e.target.value})} placeholder="توضیحات"/><select disabled={readOnly} className="wb-input" value={d.parentId} onChange={e=>setD({...d,parentId:e.target.value})}><option value="">بدون نقشه والد</option>{maps.filter(x=>x.id!==map.id).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><input disabled={readOnly} type="number" className="wb-input" value={d.displayOrder} onChange={e=>setD({...d,displayOrder:Number(e.target.value)})}/></div><Visibility value={d} onChange={setD} disabled={readOnly}/>{!readOnly&&<button className="wb-primary mt-2" onClick={()=>void onSave(d)}>ذخیره تنظیمات نقشه</button>}</details>}
function ResourceEditor({kind,resource,resources,theme,onSave,onDelete,onClose,readOnly}:{kind:string;resource?:Resource;resources:Resource[];theme:'light'|'dark';onSave:(v:any)=>Promise<void>;onDelete?:()=>Promise<void>;onClose:()=>void;readOnly:boolean}){const schema=kind==='lore'?loreFields:kind==='artifact'?artifactFields:kind==='power_system'?powerFields:kind==='timeline'?['calendarSystem','eraSettings']:[];const[draft,setDraft]=useState<any>(()=>({name:resource?.name||'',subtype:resource?.subtype||'',description:resource?.description||'',visibility:resource?.visibility||'draft',publicationStatus:resource?.publication_status||'draft',displayOrder:resource?.display_order||0,data:{...(resource?.data||{}),relatedIds:resource?.data?.relatedIds||[]}}));const[saving,setSaving]=useState<'idle'|'saving'|'saved'|'failed'>('idle'),[preview,setPreview]=useState(readOnly),[dirty,setDirty]=useState(false),[errors,setErrors]=useState<any>({}),changeVersion=useRef(0),savingRef=useRef(false),dialogRef=useDialogFocus();const close=()=>{if(!dirty||confirm('تغییرات ذخیره‌نشده دور ریخته شوند؟'))onClose()};const edit=(next:any)=>{changeVersion.current++;setDraft(next);setDirty(true)};const save=useCallback(async()=>{if(savingRef.current)return;const nextErrors:any={};if(!draft.name.trim())nextErrors.name='نام الزامی است';if(draft.publicationStatus==='published'&&!String(draft.description||draft.data.summary||'').trim())nextErrors.description='برای انتشار، توضیحات یا خلاصه الزامی است';setErrors(nextErrors);if(Object.keys(nextErrors).length)return;const version=changeVersion.current;savingRef.current=true;setSaving('saving');try{await onSave({...draft,expectedVersion:resource?.version});if(changeVersion.current===version)setDirty(false);setSaving('saved')}catch(error:any){setErrors(current=>({...current,...(error.fields||{}),form:error.message}));setSaving('failed')}finally{savingRef.current=false}},[draft,onSave]);useEffect(()=>{if(!resource||!dirty||!draft.name.trim()||readOnly)return;const id=setTimeout(()=>void save(),1200);return()=>clearTimeout(id)},[draft,dirty,readOnly]);useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue=''}};addEventListener('beforeunload',warn);return()=>removeEventListener('beforeunload',warn)},[dirty]);return <div role="dialog" aria-modal="true" aria-label={`${resource?'ویرایش':'ایجاد'} ${kindLabels[kind]||kind}`} className="fixed inset-0 z-50 bg-black/70 p-3 overflow-auto" onKeyDown={e=>{if(e.key==='Escape')close()}}><div ref={dialogRef} className="max-w-4xl mx-auto rounded-2xl border border-slate-700 bg-slate-950 p-5 space-y-4"><div className="flex justify-between"><h2 className="text-xl font-black capitalize">{resource?'ویرایش':'ایجاد'} {kindLabels[kind]||kind.replace('_',' ')}</h2><button aria-label="بستن ویرایشگر" onClick={close}><X/></button></div>{readOnly&&<p className="rounded-lg bg-amber-500/10 p-3 text-sm text-amber-300">حالت فقط‌خواندنی. برای اعمال تغییرات به پرمیوم نویسنده نیاز است.</p>}<label className="text-xs font-bold">نام<input autoFocus disabled={readOnly} className="wb-input" value={draft.name} onChange={e=>edit({...draft,name:e.target.value})}/>{errors.name&&<span className="text-rose-400">{errors.name}</span>}</label><div className="grid sm:grid-cols-2 gap-3"><label className="text-xs font-bold">نوع{typeOptions[kind]?<select disabled={readOnly} className="wb-input" value={draft.subtype} onChange={e=>edit({...draft,subtype:e.target.value})}><option value="">انتخاب نوع</option>{typeOptions[kind].map(x=><option key={x}>{x}</option>)}</select>:<input disabled={readOnly} className="wb-input" value={draft.subtype} onChange={e=>edit({...draft,subtype:e.target.value})}/>}</label>{kind==='artifact'&&<label className="text-xs font-bold">سطح کمیابی<select disabled={readOnly} className="wb-input" value={draft.data.rarity||'Common'} onChange={e=>edit({...draft,data:{...draft.data,rarity:e.target.value}})}>{['Common','Uncommon','Rare','Legendary','Mythic'].map(x=><option key={x}>{x}</option>)}</select></label>}</div><div className="flex justify-between items-center"><span className="text-xs font-bold">توضیحات</span><button type="button" className="wb-secondary" onClick={()=>setPreview(v=>!v)}>{preview?'حالت ویرایش':'پیش‌نمایش'}</button></div><label className="block text-xs font-bold"><TiptapEditor theme={theme} content={draft.description} readOnly={readOnly||preview} internalLinks={resources.filter(r=>r.id!==resource?.id).map(r=>({id:r.id,name:r.name,href:`?resource=${encodeURIComponent(r.id)}`}))} onChange={description=>edit({...draft,description})}/>{errors.description&&<span className="text-rose-400">{errors.description}</span>}</label><div className="grid md:grid-cols-2 gap-3">{schema.map(field=><label key={field} className="text-xs font-bold capitalize">{fieldLabels[field]||field.replace(/([A-Z])/g,' $1')}<textarea disabled={readOnly} className="wb-input min-h-20" value={draft.data[field]||''} onChange={e=>edit({...draft,data:{...draft.data,[field]:e.target.value}})}/></label>)}</div>{kind==='power_system'&&<NestedList title="سطوح پیشرفت" value={draft.data.progressionLevels||[]} onChange={v=>edit({...draft,data:{...draft.data,progressionLevels:v}})} disabled={readOnly}/>} {kind==='power_system'&&<NestedList title="دسته‌ها و تکنیک‌ها" value={draft.data.categories||[]} onChange={v=>edit({...draft,data:{...draft.data,categories:v}})} disabled={readOnly}/>}<EntityPicker resources={resources.filter(r=>r.id!==resource?.id)} value={draft.data.relatedIds} onChange={relatedIds=>edit({...draft,data:{...draft.data,relatedIds}})} disabled={readOnly}/><label className="text-xs font-bold">برچسب‌ها (با ویرگول جدا شوند)<input disabled={readOnly} className="wb-input" value={(draft.data.tags||[]).join(', ')} onChange={e=>edit({...draft,data:{...draft.data,tags:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)}})}/></label><label className="text-xs font-bold">تصاویر (هر URL در یک خط)<textarea disabled={readOnly} className="wb-input" value={(draft.data.images||[]).join('\n')} onChange={e=>edit({...draft,data:{...draft.data,images:e.target.value.split('\n').filter(Boolean)}})}/></label><Visibility value={draft} onChange={edit} disabled={readOnly}/><RevisionHistory resource={resource}/>{errors.form&&<p role="alert" className="text-xs text-rose-400">{errors.form}</p>}<div className="flex items-center gap-2"><button disabled={readOnly||saving==='saving'} onClick={()=>void save()} className="wb-primary"><Save className="w-4 h-4"/> ذخیره</button>{onDelete&&!readOnly&&<button onClick={()=>{if(confirm(`${draft.name} حذف شود؟ این عمل بازگشت‌پذیر نیست.`))void onDelete()}} className="wb-danger"><Trash2 className="w-4 h-4"/> حذف</button>}<span role="status" className="text-xs opacity-60">{saving==='saving'?'در حال ذخیره…':saving==='saved'?'ذخیره شد':saving==='failed'?'ذخیره ناموفق بود — دوباره تلاش کنید':''}</span></div></div></div>}
function NestedList({title,value,onChange,disabled}:{title:string;value:any[];onChange:(v:any[])=>void;disabled:boolean}){return <fieldset disabled={disabled} className="rounded-xl border border-slate-700 p-3"><legend className="px-1 text-xs font-bold">{title}</legend>{value.map((x,i)=><div key={x.id||i} className="flex gap-2 mb-2"><button type="button" disabled={i===0} onClick={()=>{const n=[...value];[n[i-1],n[i]]=[n[i],n[i-1]];onChange(n)}} aria-label="انتقال به بالا">↑</button><input className="wb-input" value={x.name||''} onChange={e=>onChange(value.map((v,j)=>j===i?{...v,name:e.target.value,order:i}:v))}/><button type="button" onClick={()=>onChange(value.filter((_,j)=>j!==i))} aria-label="حذف">×</button></div>)}<button type="button" className="text-xs text-violet-400" onClick={()=>onChange([...value,{id:crypto.randomUUID(),name:'',order:value.length,children:[]}])}>+ افزودن مورد</button></fieldset>}
